@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=DM+Mono:wght@400;500&display=swap');
:root{--ink:#071014;--mint:#9dffd4;--cyan:#52d9e8;--cream:#e9f4ed;--muted:#91a39f;--line:rgba(166,242,219,.18);font-family:'Barlow Condensed',Arial,sans-serif;color:var(--cream);font-synthesis:none}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#050b0e}body{user-select:none}#game-shell{position:relative;width:100%;height:100%;overflow:hidden;background:#061014}canvas{display:block;width:100%;height:100%;image-rendering:pixelated}.scanlines{position:absolute;inset:0;pointer-events:none;z-index:2;background:repeating-linear-gradient(0deg,rgba(0,0,0,.045) 0px,rgba(0,0,0,.045) 1px,transparent 1px,transparent 4px);mix-blend-mode:multiply}.hud{position:absolute;inset:0;z-index:3;pointer-events:none}.hidden{display:none!important}.topbar{position:absolute;left:0;right:0;top:0;height:82px;padding:17px 30px;display:flex;align-items:center;gap:26px;background:linear-gradient(180deg,rgba(3,10,13,.83),rgba(3,10,13,.2),transparent)}.brand{display:flex;align-items:center;gap:11px;min-width:220px}.brand-mark{font-size:27px;color:var(--mint);text-shadow:0 0 20px #74f5c2}.brand b{display:block;font-size:17px;letter-spacing:2px;line-height:1}.brand small,.objective small,.bottom-hud small,.right-hud small{display:block;color:#9badab;font-family:'DM Mono',monospace;font-size:9px;letter-spacing:1.3px;margin-top:5px}.wave-chip{font-family:'DM Mono',monospace;font-size:11px;letter-spacing:1.2px;color:#b1c5be;border:1px solid var(--line);padding:9px 13px;background:rgba(9,24,27,.56)}.wave-chip b{color:var(--mint);font-size:16px;margin-left:6px}.live-dot,.eyebrow span{display:inline-block;width:6px;height:6px;border-radius:50%;background:#79f4be;box-shadow:0 0 12px #79f4be;margin-right:8px}.objective{margin-left:auto;text-align:right}.objective b{font-size:17px;letter-spacing:.5px}.left-hud{position:absolute;left:30px;bottom:30px;width:210px;padding:14px 16px;background:linear-gradient(100deg,rgba(5,15,18,.83),rgba(6,17,20,.36));border-left:2px solid rgba(123,245,197,.58)}.stat-label{display:flex;justify-content:space-between;font-family:'DM Mono',monospace;font-size:10px;letter-spacing:1.3px;color:#b7c8c1}.stat-label b{color:#e9f4ed;font-size:13px}.meter{height:5px;background:rgba(186,221,207,.14);margin:8px 0 13px}.meter i{height:100%;width:100%;display:block;background:linear-gradient(90deg,#50e6a3,#a9ffd0);box-shadow:0 0 10px rgba(80,230,163,.45);transition:width .2s}.shield-label{color:#83cad1}.shield-meter{margin-bottom:0}.shield-meter i{background:linear-gradient(90deg,#3badd0,#8ff4ed);box-shadow:0 0 10px rgba(59,173,208,.42)}.right-hud{position:absolute;right:30px;bottom:30px;display:flex;gap:24px;align-items:flex-end;text-align:right}.kills{display:flex;align-items:center;gap:10px;text-align:left}.kills b{display:block;color:var(--mint);font-family:'DM Mono',monospace;font-size:24px;line-height:1}.kills small{font-size:8px}.skull{font-size:25px;color:#9bffe0}.score b{font-family:'DM Mono',monospace;color:#eaf6ed;font-size:19px}.bottom-hud{position:absolute;left:50%;bottom:26px;transform:translateX(-50%);display:flex;align-items:flex-end;gap:25px;padding:10px 18px;background:linear-gradient(90deg,transparent,rgba(5,14,17,.75) 12%,rgba(5,14,17,.75) 88%,transparent)}.weapon-card{display:flex;align-items:center;gap:12px;min-width:230px}.weapon-icon{display:grid;place-items:center;width:44px;height:44px;border:1px solid rgba(113,225,199,.3);color:#89f4ca;font-size:24px;background:rgba(36,103,91,.16)}.weapon-card b{display:block;font-size:16px;letter-spacing:1.1px}.weapon-card small{margin:0 0 3px;font-size:8px}.weapon-card span{display:block;color:#8da39c;font:8px 'DM Mono',monospace;letter-spacing:1px;margin-top:3px}.ammo{min-width:93px;text-align:right;padding-bottom:2px}.ammo>b{font:30px 'DM Mono',monospace;color:#eaf6ed}.ammo>span{font:14px 'DM Mono',monospace;color:#a6c1b6}.ammo>span i{font-style:normal}.ammo small{font-size:8px}.crosshair{position:absolute;top:50%;left:50%;width:27px;height:27px;transform:translate(-50%,-50%);opacity:.88;transition:transform .08s}.crosshair i{position:absolute;background:#d3ffe9;box-shadow:0 0 5px #7af2c1}.crosshair i:nth-child(1){height:7px;width:1px;left:13px;top:0}.crosshair i:nth-child(2){height:7px;width:1px;left:13px;bottom:0}.crosshair i:nth-child(3){width:7px;height:1px;left:0;top:13px}.crosshair i:nth-child(4){width:7px;height:1px;right:0;top:13px}.crosshair b{position:absolute;width:3px;height:3px;border-radius:50%;background:#9affe0;left:12px;top:12px}.crosshair.hit{transform:translate(-50%,-50%) scale(1.45)}.message{position:absolute;top:22%;left:50%;transform:translateX(-50%);color:var(--mint);font:11px 'DM Mono',monospace;letter-spacing:2px;text-shadow:0 0 12px #4ccfa5}.damage-flash{position:absolute;inset:0;border:0 solid rgba(255,66,79,0);transition:border .1s}.damage-flash.show{border:10px solid rgba(255,66,79,.36)}.screen-panel{position:absolute;z-index:5;left:50%;top:50%;transform:translate(-50%,-50%);width:min(650px,calc(100% - 32px));text-align:center;padding:35px 36px 26px;background:linear-gradient(145deg,rgba(8,20,23,.94),rgba(7,15,18,.88));border:1px solid rgba(142,239,205,.27);box-shadow:0 30px 100px rgba(0,0,0,.62),inset 0 0 50px rgba(52,164,132,.06);backdrop-filter:blur(14px)}.screen-panel:before,.screen-panel:after{content:'';position:absolute;width:24px;height:24px;border-color:#94f9ce}.screen-panel:before{left:-1px;top:-1px;border-left:2px solid;border-top:2px solid}.screen-panel:after{right:-1px;bottom:-1px;border-right:2px solid;border-bottom:2px solid}.eyebrow{font:10px 'DM Mono',monospace;letter-spacing:2.2px;color:#a8c0b9}.eyebrow span{margin:0 11px 1px 0}.eyebrow span:last-child{margin:0 0 1px 11px}h1{font-size:82px;line-height:.75;letter-spacing:3px;margin:27px 0 23px;font-weight:900}h1 em{font-style:normal;color:var(--mint);text-shadow:0 0 28px rgba(73,245,184,.22)}.subtitle{font:12px 'DM Mono',monospace;letter-spacing:2px;color:#a1e2c6}.intro{font-size:17px;line-height:1.4;color:#a6b8b2;margin:16px 0 22px}.primary-button{position:relative;border:0;padding:14px 29px;background:var(--mint);color:#071411;font:800 16px 'Barlow Condensed',sans-serif;letter-spacing:2px;cursor:pointer;min-width:190px;box-shadow:0 0 24px rgba(99,239,182,.18);transition:transform .18s,background .18s}.primary-button:hover{background:#d0ffdf;transform:translateY(-2px)}.primary-button span{font-size:20px;margin-left:17px}.title-foot{display:flex;justify-content:space-between;margin-top:27px;color:#667d76;font:8px 'DM Mono',monospace;letter-spacing:1.3px}.controls-note{margin-top:22px;color:#79918a;font:9px 'DM Mono',monospace;letter-spacing:1px}.controls-note b{color:#bfcec6}.controls-note i{font-style:normal;color:#4ea98a;margin:0 7px}.compact{width:min(490px,calc(100% - 32px));padding:34px 30px}.compact h2{font-size:41px;letter-spacing:2px;margin:22px 0 4px}.compact p{color:#9baea7;margin:5px 0 24px}.compact .controls-note{margin-top:24px}.final-score{margin:18px auto 20px}.final-score small{display:block;font:9px 'DM Mono',monospace;color:#86a19a;letter-spacing:2px}.final-score b{display:block;color:var(--mint);font:30px 'DM Mono',monospace;margin-top:5px}.toast{position:absolute;z-index:6;left:50%;top:84px;transform:translateX(-50%);padding:7px 12px;background:rgba(6,19,21,.85);color:var(--mint);font:10px 'DM Mono',monospace;letter-spacing:1px;opacity:0;transition:opacity .2s;pointer-events:none}.toast.show{opacity:1}.mobile-controls{display:none;position:absolute;z-index:4;inset:auto 0 0;height:190px;pointer-events:none}.joystick,.fire-button,.switch-button{pointer-events:auto;touch-action:none}.joystick{position:absolute;bottom:25px;left:24px;width:110px;height:110px;border:1px solid rgba(165,238,213,.38);border-radius:50%;background:rgba(8,24,26,.42);display:grid;place-items:center}.joystick i{width:53px;height:53px;border-radius:50%;background:rgba(119,240,194,.19);border:1px solid rgba(147,255,214,.55)}.joystick b{position:absolute;width:8px;height:8px;border-radius:50%;background:#a2ffd8}.fire-button,.switch-button{position:absolute;border:1px solid rgba(160,255,220,.45);color:#d9ffea;background:rgba(7,22,23,.64);font:700 12px 'DM Mono',monospace;letter-spacing:1px;border-radius:50%;width:76px;height:76px;right:26px;bottom:35px}.fire-button{background:rgba(68,194,149,.32)}.switch-button{right:112px;bottom:76px;width:56px;height:56px;font-size:9px}.mobile-controls button:active{background:rgba(119,240,194,.46)}
@media(max-width:700px){.topbar{height:65px;padding:12px 14px;gap:10px}.brand{min-width:0;gap:7px}.brand b{font-size:13px;letter-spacing:1.2px}.brand small{font-size:7px}.brand-mark{font-size:20px}.wave-chip{font-size:8px;padding:7px}.wave-chip b{font-size:12px}.objective{display:none}.left-hud{left:12px;bottom:190px;width:145px;padding:10px 11px}.right-hud{right:12px;bottom:190px;gap:10px}.kills b{font-size:18px}.kills small,.right-hud small{font-size:7px}.skull{font-size:18px}.score b{font-size:14px}.bottom-hud{bottom:8px;left:50%;gap:8px;padding:5px 9px}.weapon-card{min-width:0;gap:7px}.weapon-icon{width:34px;height:34px;font-size:18px}.weapon-card b{font-size:11px}.weapon-card small,.weapon-card span,.ammo small{font-size:6px}.ammo{min-width:57px}.ammo>b{font-size:21px}.ammo>span{font-size:10px}.mobile-controls{display:block}.screen-panel{padding:27px 18px 20px}.eyebrow{font-size:8px;letter-spacing:1.3px}h1{font-size:61px;margin:24px 0 19px}.intro{font-size:15px}.title-foot{font-size:7px}.controls-note{font-size:7px;letter-spacing:.5px}.controls-note i{margin:0 3px}.compact h2{font-size:32px}.crosshair{top:46%}}
@media(max-height:610px) and (min-width:701px){.screen-panel{padding:22px 30px 18px}h1{font-size:64px;margin:18px 0}.intro{margin:10px 0 15px}.title-foot{margin-top:18px}.controls-note{margin-top:13px}.left-hud,.right-hud{bottom:14px}.bottom-hud{bottom:9px}}

(() => {
'use strict';
const canvas=document.querySelector('#screen'), ctx=canvas.getContext('2d',{alpha:false});
const $=s=>document.querySelector(s);
const ui={hud:$('#hud'),title:$('#title-screen'),pause:$('#pause-screen'),end:$('#end-screen'),wave:$('#wave'),health:$('#health-value'),healthBar:$('#health-bar'),shield:$('#shield-value'),shieldBar:$('#shield-bar'),kills:$('#kills'),score:$('#score'),ammo:$('#ammo'),reserve:$('#reserve'),weapon:$('#weapon-name'),weaponNo:$('#weapon-number'),weaponIcon:$('#weapon-icon'),weaponNote:$('#weapon-note'),cross:$('#crosshair'),message:$('#message'),flash:$('#damage-flash'),toast:$('#toast')};
const FOV=Math.PI/3, TAU=Math.PI*2;
const weapons=[
 {name:'PULSE SIDEARM',icon:'⌁',note:'STABLE · SEMI-AUTO',clip:12,rate:260,damage:34,pellets:1,spread:.018,color:'#8fffe0'},
 {name:'BREACH SHOTGUN',icon:'✣',note:'WIDE · CLOSE QUARTERS',clip:8,rate:650,damage:19,pellets:7,spread:.16,color:'#ffd18b'},
 {name:'VOLT CARBINE',icon:'⌗',note:'RAPID · FULL AUTO',clip:30,rate:95,damage:18,pellets:1,spread:.035,color:'#85d9ff'},
 {name:'ARC CASTER',icon:'ϟ',note:'CHAIN · ENERGY BURST',clip:10,rate:430,damage:42,pellets:1,spread:.025,color:'#c9a7ff'},
 {name:'LONGSHOT RAIL',icon:'╱',note:'PRECISION · HIGH IMPACT',clip:5,rate:720,damage:105,pellets:1,spread:.006,color:'#ff8fa8'},
 {name:'NOVA LAUNCHER',icon:'◉',note:'BLAST · AREA EFFECT',clip:4,rate:800,damage:78,pellets:1,spread:.02,color:'#ffab68'}
];
const mapRows=[
'##################','##....#.........##','#.....#..........#','#........##......#','#..##............#','#..##.....#......#','#.........#......#','###...........####','#...............##','#.....##.........#','#.....##.........#','#...........##...#','##...............#','#.......#........#','#.......#....##..#','#.................#','#....#...........##','##################'
];
let map=mapRows.map(r=>r.split('').map(c=>c==='#'?1:0));
const W=map[0].length,H=map.length;
let w=0,h=0,bufW=480,bufH=270,zbuf=new Float32Array(bufW),running=false,paused=false,gameOver=false,last=0,elapsed=0;
let player,enemies=[],particles=[],tracers=[],wave=1,kills=0,score=0,weaponIndex=0,ammo=[],reloadTimer=0,shotTimer=0,muzzle=0,damageFlash=0,hitFlash=0,bob=0,walk=0,fireHeld=false,fireCooldown=0,keys={},mouseDown=false,toastTimer=0,messageTimer=0,spawnTimer=0;
let yaw=0, joystick={x:0,y:0,active:false,pointer:null}, aimTouch=null;
function resize(){w=canvas.width=innerWidth;h=canvas.height=innerHeight;bufW=Math.max(360,Math.min(720,Math.floor(w*.62)));bufH=Math.floor(bufW*h/w);bufH=Math.max(210,Math.min(480,bufH));zbuf=new Float32Array(bufW)}
addEventListener('resize',resize);resize();
function isWall(x,y){return x<0||y<0||x>=W||y>=H||map[Math.floor(y)][Math.floor(x)]===1}
function clearShot(ax,ay,bx,by){let d=Math.hypot(bx-ax,by-ay),steps=Math.ceil(d*12);for(let i=1;i<steps;i++){let t=i/steps;if(isWall(ax+(bx-ax)*t,ay+(by-ay)*t))return false}return true}
function resetGame(){player={x:8.5,y:8.5,angle:-Math.PI/2,health:100,shield:100,damageCooldown:0};yaw=player.angle;enemies=[];particles=[];tracers=[];wave=1;kills=score=0;weaponIndex=0;ammo=weapons.map(q=>q.clip);reloadTimer=shotTimer=muzzle=damageFlash=hitFlash=bob=walk=0;fireHeld=false;spawnTimer=0;gameOver=false;paused=false;elapsed=0;spawnWave();syncHud();}
function spawnWave(){let count=Math.min(5+wave*2,24);for(let i=0;i<count;i++)spawnEnemy();showMessage(`WAVE ${String(wave).padStart(2,'0')} · ${count} SECURITY UNITS INBOUND`,2400)}
function spawnEnemy(){let p;for(let i=0;i<100;i++){let x=1.5+Math.random()*(W-3),y=1.5+Math.random()*(H-3);if(isWall(x,y)||Math.hypot(x-player.x,y-player.y)<5||enemies.some(e=>Math.hypot(e.x-x,e.y-y)<1))continue;p={x,y};break}if(!p)return;enemies.push({x:p.x,y:p.y,hp:65+Math.min(wave*5,45),max:65+Math.min(wave*5,45),speed:.45+Math.random()*.16,attack:Math.random()*.6,phase:Math.random()*TAU,flash:0,alive:true,kind:Math.random()<.25?'scout':'unit',seed:Math.random()*100});}
function start(){resetGame();ui.title.classList.add('hidden');ui.end.classList.add('hidden');ui.pause.classList.add('hidden');ui.hud.classList.remove('hidden');running=true;paused=false;last=performance.now();requestAnimationFrame(frame);if(matchMedia('(pointer:fine)').matches)canvas.requestPointerLock?.()}
function pause(){if(!running||gameOver)return;paused=!paused;ui.pause.classList.toggle('hidden',!paused);if(paused)document.exitPointerLock?.();else{last=performance.now();if(matchMedia('(pointer:fine)').matches)canvas.requestPointerLock?.();requestAnimationFrame(frame)}}
function endGame(victory=false){gameOver=true;running=false;fireHeld=false;ui.hud.classList.add('hidden');ui.end.classList.remove('hidden');$('#end-title').textContent=victory?'SECTOR SECURED':'SUIT SYSTEMS OFFLINE';$('#end-copy').textContent=victory?'All units cleared. Outpost 09 is yours again.':'The security grid overwhelmed your suit. Ready for another run?';$('#final-score').textContent=String(score).padStart(6,'0');document.exitPointerLock?.()}
function showMessage(s,ms=1200){ui.message.textContent=s;messageTimer=ms}
function toast(s){ui.toast.textContent=s;ui.toast.classList.add('show');toastTimer=1150}
function syncHud(){ui.wave.textContent=String(wave).padStart(2,'0');ui.health.textContent=Math.ceil(player.health);ui.healthBar.style.width=Math.max(0,player.health)+'%';ui.shield.textContent=Math.ceil(player.shield);ui.shieldBar.style.width=Math.max(0,player.shield)+'%';ui.kills.textContent=String(kills).padStart(3,'0');ui.score.textContent=String(score).padStart(6,'0');ui.ammo.textContent=ammo[weaponIndex];ui.weapon.textContent=weapons[weaponIndex].name;ui.weaponNo.textContent=String(weaponIndex+1).padStart(2,'0');ui.weaponIcon.textContent=weapons[weaponIndex].icon;ui.weaponNote.textContent=weapons[weaponIndex].note;}
function setWeapon(n){weaponIndex=(n+weapons.length)%weapons.length;reloadTimer=0;syncHud();toast(weapons[weaponIndex].name)}
function reload(){let gun=weapons[weaponIndex];if(reloadTimer>0||ammo[weaponIndex]>=gun.clip)return;reloadTimer=gun.reload||950;fireHeld=false;showMessage('RECHARGING',reloadTimer)}
function hitEnemy(e,damage){e.hp-=damage;e.flash=.13;hitFlash=100;let ang=Math.atan2(e.y-player.y,e.x-player.x);for(let n=0;n<5;n++)particles.push({x:e.x,y:e.y,z:.5+Math.random()*.8,vx:Math.cos(ang+Math.random()*1.8-0.9)*(1+Math.random()*1.8),vy:Math.sin(ang+Math.random()*1.8-0.9)*(1+Math.random()*1.8),life:.22+Math.random()*.23,max:.45,color:['#8cffe1','#5ce8ff','#e5ffd7'][n%3],size:1+Math.random()*2});if(e.hp<=0){e.alive=false;kills++;score+=100+wave*10;for(let n=0;n<13;n++)particles.push({x:e.x,y:e.y,z:Math.random()*1.3,vx:(Math.random()-.5)*3,vy:(Math.random()-.5)*3,life:.35+Math.random()*.42,max:.75,color:['#8affd5','#62d5ed','#ffd17a'][n%3],size:1.5+Math.random()*3});syncHud();}}
function shoot(){if(!running||paused||gameOver||reloadTimer>0||shotTimer>0)return;let gun=weapons[weaponIndex];if(ammo[weaponIndex]<=0){toast('EMPTY · PRESS R');shotTimer=180;return}ammo[weaponIndex]--;shotTimer=gun.rate;fireCooldown=90;muzzle=.12;syncHud();let hitAny=false;for(let p=0;p<gun.pellets;p++){let spread=(Math.random()-.5)*gun.spread;let ang=player.angle+spread;let nearest=Infinity,target=null;for(let e of enemies){if(!e.alive)continue;let dx=e.x-player.x,dy=e.y-player.y,dist=Math.hypot(dx,dy),diff=Math.atan2(Math.sin(Math.atan2(dy,dx)-ang),Math.cos(Math.atan2(dy,dx)-ang));let threshold=Math.atan2(e.kind==='scout'?.22:.29,dist);if(Math.abs(diff)<threshold&&dist<nearest&&clearShot(player.x,player.y,e.x,e.y)){nearest=dist;target=e}}
if(target){hitEnemy(target,gun.damage*(1+(Math.random()*.16)));hitAny=true;tracers.push({x:player.x,y:player.y,tx:target.x,ty:target.y,life:.09,color:gun.color})}else{let tx=player.x+Math.cos(ang)*7,ty=player.y+Math.sin(ang)*7;tracers.push({x:player.x,y:player.y,tx,ty,life:.065,color:gun.color})}}
if(hitAny){ui.cross.classList.add('hit');setTimeout(()=>ui.cross.classList.remove('hit'),90)}
}
function damagePlayer(amount){if(player.damageCooldown>0)return;player.damageCooldown=.5;let absorbed=Math.min(player.shield,amount);player.shield-=absorbed;player.health-=amount-absorbed;damageFlash=190;ui.flash.classList.add('show');setTimeout(()=>ui.flash.classList.remove('show'),150);syncHud();if(player.health<=0)endGame(false)}

