// Distant atmospheric bands and floor grid
c.fillStyle='rgba(151,235,194,.13)';c.fillRect(0,Hp*.475,Wp,1);c.strokeStyle='rgba(118,205,172,.09)';c.lineWidth=1;for(let i=1;i<10;i++){let y=Hp*.5+i*i*2.7;if(y<Hp){c.beginPath();c.moveTo(0,y);c.lineTo(Wp,y);c.stroke()}}for(let x=0;x<Wp;x+=Wp/12){c.beginPath();c.moveTo(Wp/2+(x-Wp/2)*.07,Hp*.49);c.lineTo(x,Hp);c.stroke()}
