let visible=enemies.map(e=>{let dx=e.x-player.x,dy=e.y-player.y,dist=Math.hypot(dx,dy),diff=Math.atan2(Math.sin(Math.atan2(dy,dx)-player.angle),Math.cos(Math.atan2(dy,dx)-player.angle));return{e,dist,diff,x:Wp/2+Math.tan(diff)*focal}}).filter(o=>Math.abs(o.diff)<FOV*.85&&o.dist>.1).sort((a,b)=>b.dist-a.dist);
for(let o of visible){let {e,dist,x}=o;let eh=Math.min(Hp*1.2,focal*(e.kind==='scout'?1.0:1.28)/dist),ey=Hp*.5-eh*.49+Math.sin(e.phase)*1.3,ew=eh*(e.kind==='scout'?.49:.56);if(x+ew<0||x-ew>Wp)continue;let idx=Math.max(0,Math.min(Wp-1,Math.floor(x))),occluded=zbuf[idx]<dist-.2;if(occluded)continue;drawEnemy(c,x,ey,ew,eh,e,dist);}
