(() => {
'use strict';
const canvas=document.querySelector('#screen'), ctx=canvas.getContext('2d',{alpha:false});
const $=s=>document.querySelector(s);
const ui={hud:$('#hud'),title:$('#title-screen'),pause:$('#pause-screen'),end:$('#end-screen'),wave:$('#wave'),health:$('#health-value'),healthBar:$('#health-bar'),shield:$('#shield-value'),shieldBar:$('#shield-bar'),kills:$('#kills'),score:$('#score'),ammo:$('#ammo'),reserve:$('#reserve'),weapon:$('#weapon-name'),weaponNo:$('#weapon-number'),weaponIcon:$('#weapon-icon'),weaponNote:$('#weapon-note'),cross:$('#crosshair'),message:$('#message'),flash:$('#damage-flash'),toast:$('#toast')};
const FOV=Math.PI/3, TAU=Math.PI*2;
const weapons=[
 {name:'PULSE SIDEARM',icon:'⌁',note:'STABLE · SEMI-AUTO',clip:12,rate:260,damage:34,pellets:1,spread:.018,color:'#8fffe0'},
 {name:'BREACH SHOTGUN',icon:'✣',note:'WIDE · CLOSE QUARTERS',clip:8,rate:650,damage:19,pellets:7,spread:.16,color:'#ffd18b'},
 {name:'VOLT CARBINE',icon:'⌗',note:'RAPID · FULL AUTO',clip:30,rate:95,damage:18,pellets:1,spread:.035,color:'#85d9ff'},
 {name:'ARC CASTER',icon:'ϟ',note:'CHAIN · ENERGY BURST',clip:10,rate:430,damage:42,pellets:1,spread:.025,color:'#c9a7ff'},
 {name:'LONGSHOT RAIL',icon:'╱',note:'PRECISION · HIGH IMPACT',clip:5,rate:720,damage:105,pellets:1,spread:.006,color:'#ff8fa8'},
 {name:'NOVA LAUNCHER',icon:'◉',note:'BLAST · AREA EFFECT',clip:4,rate:800,damage:78,pellets:1,spread:.02,color:'#ffab68'}
];
const mapRows=[
'##################','##....#.........##','#.....#..........#','#........##......#','#..##............#','#..##.....#......#','#.........#......#','###...........####','#...............##','#.....##.........#','#.....##.........#','#...........##...#','##...............#','#.......#........#','#.......#....##..#','#.................#','#....#...........##','##################'
];
let map=mapRows.map(r=>r.split('').map(c=>c==='#'?1:0));
const W=map[0].length,H=map.length;
let w=0,h=0,bufW=480,bufH=270,zbuf=new Float32Array(bufW),running=false,paused=false,gameOver=false,last=0,elapsed=0;
let player,enemies=[],particles=[],tracers=[],wave=1,kills=0,score=0,weaponIndex=0,ammo=[],reloadTimer=0,shotTimer=0,muzzle=0,damageFlash=0,hitFlash=0,bob=0,walk=0,fireHeld=false,fireCooldown=0,keys={},mouseDown=false,toastTimer=0,messageTimer=0,spawnTimer=0;
let yaw=0, joystick={x:0,y:0,active:false,pointer:null}, aimTouch=null;
function resize(){w=innerWidth;h=innerHeight;bufW=Math.max(360,Math.min(720,Math.floor(w*.62)));bufH=Math.floor(bufW*h/w);bufH=Math.max(210,Math.min(480,bufH));canvas.width=bufW;canvas.height=bufH;zbuf=new Float32Array(bufW)}
addEventListener('resize',resize);resize();
function isWall(x,y){return x<0||y<0||x>=W||y>=H||map[Math.floor(y)][Math.floor(x)]===1}
function clearShot(ax,ay,bx,by){let d=Math.hypot(bx-ax,by-ay),steps=Math.ceil(d*12);for(let i=1;i<steps;i++){let t=i/steps;if(isWall(ax+(bx-ax)*t,ay+(by-ay)*t))return false}return true}
function resetGame(){player={x:8.5,y:8.5,angle:-Math.PI/2,health:100,shield:100,damageCooldown:0};yaw=player.angle;enemies=[];particles=[];tracers=[];wave=1;kills=score=0;weaponIndex=0;ammo=weapons.map(q=>q.clip);reloadTimer=shotTimer=muzzle=damageFlash=hitFlash=bob=walk=0;fireHeld=false;spawnTimer=0;gameOver=false;paused=false;elapsed=0;spawnWave();syncHud();}
function spawnWave(){let count=Math.min(5+wave*2,24);for(let i=0;i<count;i++)spawnEnemy();showMessage(`WAVE ${String(wave).padStart(2,'0')} · ${count} SECURITY UNITS INBOUND`,2400)}
function spawnEnemy(){let p;for(let i=0;i<100;i++){let x=1.5+Math.random()*(W-3),y=1.5+Math.random()*(H-3);if(isWall(x,y)||Math.hypot(x-player.x,y-player.y)<5||enemies.some(e=>Math.hypot(e.x-x,e.y-y)<1))continue;p={x,y};break}if(!p)return;enemies.push({x:p.x,y:p.y,hp:65+Math.min(wave*5,45),max:65+Math.min(wave*5,45),speed:.45+Math.random()*.16,attack:Math.random()*.6,phase:Math.random()*TAU,flash:0,alive:true,kind:Math.random()<.25?'scout':'unit',seed:Math.random()*100});}
function start(){resetGame();ui.title.classList.add('hidden');ui.end.classList.add('hidden');ui.pause.classList.add('hidden');ui.hud.classList.remove('hidden');running=true;paused=false;last=performance.now();requestAnimationFrame(frame);if(matchMedia('(pointer:fine)').matches)canvas.requestPointerLock?.()}
function pause(){if(!running||gameOver)return;paused=!paused;ui.pause.classList.toggle('hidden',!paused);if(paused)document.exitPointerLock?.();else{last=performance.now();if(matchMedia('(pointer:fine)').matches)canvas.requestPointerLock?.();requestAnimationFrame(frame)}}
function endGame(victory=false){gameOver=true;running=false;fireHeld=false;ui.hud.classList.add('hidden');ui.end.classList.remove('hidden');$('#end-title').textContent=victory?'SECTOR SECURED':'SUIT SYSTEMS OFFLINE';$('#end-copy').textContent=victory?'All units cleared. Outpost 09 is yours again.':'The security grid overwhelmed your suit. Ready for another run?';$('#final-score').textContent=String(score).padStart(6,'0');document.exitPointerLock?.()}
function showMessage(s,ms=1200){ui.message.textContent=s;messageTimer=ms}
function toast(s){ui.toast.textContent=s;ui.toast.classList.add('show');toastTimer=1150}
function syncHud(){ui.wave.textContent=String(wave).padStart(2,'0');ui.health.textContent=Math.ceil(player.health);ui.healthBar.style.width=Math.max(0,player.health)+'%';ui.shield.textContent=Math.ceil(player.shield);ui.shieldBar.style.width=Math.max(0,player.shield)+'%';ui.kills.textContent=String(kills).padStart(3,'0');ui.score.textContent=String(score).padStart(6,'0');ui.ammo.textContent=ammo[weaponIndex];ui.weapon.textContent=weapons[weaponIndex].name;ui.weaponNo.textContent=String(weaponIndex+1).padStart(2,'0');ui.weaponIcon.textContent=weapons[weaponIndex].icon;ui.weaponNote.textContent=weapons[weaponIndex].note;}
