function reload(){let gun=weapons[weaponIndex];if(reloadTimer>0||ammo[weaponIndex]>=gun.clip)return;reloadTimer=gun.reload||950;fireHeld=false;showMessage('RECHARGING',reloadTimer)}
function hitEnemy(e,damage){e.hp-=damage;e.flash=.13;hitFlash=100;let ang=Math.atan2(e.y-player.y,e.x-player.x);for(let n=0;n<5;n++)particles.push({x:e.x,y:e.y,z:.5+Math.random()*.8,vx:Math.cos(ang+Math.random()*1.8-0.9)*(1+Math.random()*1.8),vy:Math.sin(ang+Math.random()*1.8-0.9)*(1+Math.random()*1.8),life:.22+Math.random()*.23,max:.45,color:['#8cffe1','#5ce8ff','#e5ffd7'][n%3],size:1+Math.random()*2});if(e.hp<=0){e.alive=false;kills++;score+=100+wave*10;for(let n=0;n<13;n++)particles.push({x:e.x,y:e.y,z:Math.random()*1.3,vx:(Math.random()-.5)*3,vy:(Math.random()-.5)*3,life:.35+Math.random()*.42,max:.75,color:['#8affd5','#62d5ed','#ffd17a'][n%3],size:1.5+Math.random()*3});syncHud();}}
function shoot(){if(!running||paused||gameOver||reloadTimer>0||shotTimer>0)return;let gun=weapons[weaponIndex];if(ammo[weaponIndex]<=0){toast('EMPTY · PRESS R');shotTimer=180;return}ammo[weaponIndex]--;shotTimer=gun.rate;fireCooldown=90;muzzle=.12;syncHud();let hitAny=false;for(let p=0;p<gun.pellets;p++){let spread=(Math.random()-.5)*gun.spread;let ang=player.angle+spread;let nearest=Infinity,target=null;for(let e of enemies){if(!e.alive)continue;let dx=e.x-player.x,dy=e.y-player.y,dist=Math.hypot(dx,dy),diff=Math.atan2(Math.sin(Math.atan2(dy,dx)-ang),Math.cos(Math.atan2(dy,dx)-ang));let threshold=Math.atan2(e.kind==='scout'?.22:.29,dist);if(Math.abs(diff)<threshold&&dist<nearest&&clearShot(player.x,player.y,e.x,e.y)){nearest=dist;target=e}}
if(target){hitEnemy(target,gun.damage*(1+(Math.random()*.16)));hitAny=true;tracers.push({x:player.x,y:player.y,tx:target.x,ty:target.y,life:.09,color:gun.color})}else{let tx=player.x+Math.cos(ang)*7,ty=player.y+Math.sin(ang)*7;tracers.push({x:player.x,y:player.y,tx,ty,life:.065,color:gun.color})}}
if(hitAny){ui.cross.classList.add('hit');setTimeout(()=>ui.cross.classList.remove('hit'),90)}
}
function damagePlayer(amount){if(player.damageCooldown>0)return;player.damageCooldown=.5;let absorbed=Math.min(player.shield,amount);player.shield-=absorbed;player.health-=amount-absorbed;damageFlash=190;ui.flash.classList.add('show');setTimeout(()=>ui.flash.classList.remove('show'),150);syncHud();if(player.health<=0)endGame(false)}
function update(dt){let dtS=Math.min(.05,dt/1000);elapsed+=dtS;if(shotTimer>0)shotTimer-=dt;if(reloadTimer>0){reloadTimer-=dt;if(reloadTimer<=0){ammo[weaponIndex]=weapons[weaponIndex].clip;syncHud();showMessage('CHARGED',700)}}if(muzzle>0)muzzle-=dtS;if(player.damageCooldown>0)player.damageCooldown-=dtS;if(messageTimer>0){messageTimer-=dt;if(messageTimer<=0)ui.message.textContent=''}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}if(hitFlash>0)hitFlash-=dt;
let forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)-joystick.y;let strafe=(keys.KeyD?1:0)-(keys.KeyA?1:0)+joystick.x;let mag=Math.hypot(forward,strafe);if(mag>1){forward/=mag;strafe/=mag}let speed=3.0;let dx=(Math.cos(player.angle)*forward-Math.sin(player.angle)*strafe)*speed*dtS,dy=(Math.sin(player.angle)*forward+Math.cos(player.angle)*strafe)*speed*dtS;if(!isWall(player.x+dx+.19*Math.sign(dx),player.y))player.x+=dx;if(!isWall(player.x,player.y+dy+.19*Math.sign(dy)))player.y+=dy;if(mag>.08)walk+=dtS*10;else walk*=.86;bob=Math.sin(walk)*Math.min(1,mag)*3;
if(keys.ArrowLeft)player.angle-=dtS*1.8;if(keys.ArrowRight)player.angle+=dtS*1.8;if(mouseDown&&document.pointerLockElement!==canvas){/* touchscreen aim uses its own gesture */}if(fireHeld||keys.Space)shoot();
for(let e of enemies){if(!e.alive)continue;e.phase+=dtS*3;e.flash=Math.max(0,e.flash-dtS);let d=Math.hypot(player.x-e.x,player.y-e.y);if(d>1.05){let a=Math.atan2(player.y-e.y,player.x-e.x),vx=Math.cos(a)*e.speed*dtS,vy=Math.sin(a)*e.speed*dtS;if(!isWall(e.x+vx, e.y))e.x+=vx;if(!isWall(e.x,e.y+vy))e.y+=vy}else{e.attack-=dtS;if(e.attack<=0){damagePlayer(8+Math.random()*5);e.attack=1.05+Math.random()*.55}}}
enemies=enemies.filter(e=>e.alive);for(let p of particles){p.x+=p.vx*dtS;p.y+=p.vy*dtS;p.z+=dtS*1.1;p.vx*=.96;p.vy*=.96;p.life-=dtS}particles=particles.filter(p=>p.life>0);for(let t of tracers)t.life-=dtS;tracers=tracers.filter(t=>t.life>0);
if(enemies.length===0){spawnTimer+=dt;if(spawnTimer>1100){wave++;spawnTimer=0;player.shield=Math.min(100,player.shield+14);player.health=Math.min(100,player.health+7);syncHud();spawnWave()}}else spawnTimer=0;}
function render(){const c=ctx,Wp=bufW,Hp=bufH;c.imageSmoothingEnabled=false;c.fillStyle='#101d22';c.fillRect(0,0,Wp,Hp);
let sky=c.createLinearGradient(0,0,0,Hp*.56);sky.addColorStop(0,'#091319');sky.addColorStop(.7,'#1b3031');sky.addColorStop(1,'#243533');c.fillStyle=sky;c.fillRect(0,0,Wp,Hp*.52);let floor=c.createLinearGradient(0,Hp*.48,0,Hp);floor.addColorStop(0,'#273b37');floor.addColorStop(.35,'#132521');floor.addColorStop(1,'#071211');c.fillStyle=floor;c.fillRect(0,Hp*.48,Wp,Hp*.52);
// Distant atmospheric bands and floor grid
c.fillStyle='rgba(151,235,194,.13)';c.fillRect(0,Hp*.475,Wp,1);c.strokeStyle='rgba(118,205,172,.09)';c.lineWidth=1;for(let i=1;i<10;i++){let y=Hp*.5+i*i*2.7;if(y<Hp){c.beginPath();c.moveTo(0,y);c.lineTo(Wp,y);c.stroke()}}for(let x=0;x<Wp;x+=Wp/12){c.beginPath();c.moveTo(Wp/2+(x-Wp/2)*.07,Hp*.49);c.lineTo(x,Hp);c.stroke()}
const focal=Wp/(2*Math.tan(FOV/2));for(let x=0;x<Wp;x++){let ray=player.angle+Math.atan((x-Wp/2)/focal),rx=Math.cos(ray),ry=Math.sin(ray),mx=Math.floor(player.x),my=Math.floor(player.y),ddx=Math.abs(1/rx),ddy=Math.abs(1/ry),sx=rx<0?-1:1,sy=ry<0?-1:1,sdx=(rx<0?player.x-mx:mx+1-player.x)*ddx,sdy=(ry<0?player.y-my:my+1-player.y)*ddy,side=0,steps=0;while(steps++<40){if(sdx<sdy){sdx+=ddx;mx+=sx;side=0}else{sdy+=ddy;my+=sy;side=1}if(mx<0||my<0||mx>=W||my>=H||map[my][mx])break}let dist=side===0?(mx-player.x+(1-sx)/2)/rx:(my-player.y+(1-sy)/2)/ry;dist=Math.max(.08,dist*Math.cos(ray-player.angle));zbuf[x]=dist;let wallH=Math.min(Hp*2,focal*1.2/dist),top=Math.floor(Hp*.5-wallH*.5),bot=Math.floor(Hp*.5+wallH*.5);let wallX=side===0?player.y+dist*ry:player.x+dist*rx;wallX-=Math.floor(wallX);let stripe=(Math.floor(wallX*8)%8===0);let shade=Math.max(.22,1-dist/12)*(side===0?1:.76);let r=Math.floor((stripe?56:42)*shade),g=Math.floor((stripe?119:99)*shade),b=Math.floor((stripe?104:91)*shade);c.fillStyle=`rgb(${r},${g},${b})`;c.fillRect(x,top,1,bot-top);if(stripe){c.fillStyle=`rgba(157,255,212,${.22*shade})`;c.fillRect(x,top,1,Math.max(1,wallH*.035))}c.fillStyle=`rgba(1,7,9,${Math.min(.6,dist/19)})`;c.fillRect(x,top,1,bot-top)}
// distant lamps and atmospheric glow
for(let i=0;i<7;i++){let a=player.angle+(i-3)*.18,dx=Math.cos(a),dy=Math.sin(a),distance=6.2;if(!isWall(player.x+dx*distance,player.y+dy*distance)){let sx=Wp/2+Math.tan(a-player.angle)*focal,sy=Hp*.5-focal*.25/distance;if(sx>0&&sx<Wp){c.fillStyle='rgba(119,255,201,.72)';c.fillRect(sx-2,sy,4,3);c.fillStyle='rgba(92,246,193,.08)';c.fillRect(sx-8,sy-7,16,14)}}}
let visible=enemies.map(e=>{let dx=e.x-player.x,dy=e.y-player.y,dist=Math.hypot(dx,dy),diff=Math.atan2(Math.sin(Math.atan2(dy,dx)-player.angle),Math.cos(Math.atan2(dy,dx)-player.angle));return{e,dist,diff,x:Wp/2+Math.tan(diff)*focal}}).filter(o=>Math.abs(o.diff)<FOV*.85&&o.dist>.1).sort((a,b)=>b.dist-a.dist);
